changeSet.sql:
CREATE TABLE IF NOT EXISTS settings (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL UNIQUE,
    heal_enabled BOOLEAN NOT NULL DEFAULT TRUE,
    recovery_tries INT NOT NULL DEFAULT 1,
    score_cap NUMERIC(3, 2) NOT NULL DEFAULT 0.60,
    healed_type VARCHAR(20) NOT NULL DEFAULT 'css',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

ALTER TABLE settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE settings FORCE ROW LEVEL SECURITY;

DO $$ BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_policies
        WHERE schemaname = current_schema()
          AND tablename = 'settings'
          AND policyname = 'settings_tenant_isolation'
    ) THEN
        EXECUTE 'CREATE POLICY settings_tenant_isolation ON settings '
             || 'USING (tenant_id = NULLIF(current_setting(''app.tenant_id'', true), '''')::uuid) '
             || 'WITH CHECK (tenant_id = NULLIF(current_setting(''app.tenant_id'', true), '''')::uuid)';
    END IF;

    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'healenium_app') THEN
        GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE settings TO healenium_app;
    END IF;
END $$;
